  it('keeps curated soft internal-flow recommendations visible for L5 review without promoting them as dependencies', () => {
    const report = collectConstructionDependencyRuleSystemReport(20000)
    const l5UnmatchedStableEdges = report.processConstraintBackValidation.topUnmatchedExistingRelationEdges
      .flatMap((pair) => pair.exampleStableCodes)
    const chinaNodes = flattenChinaTemplateCatalog()
    const domainNodes = flattenCatalogNodes(DOMAIN_WBS_TEMPLATE_CATALOGS.flatMap((catalog) => catalog.divisions))
    const softRecommendationEdges = [
      'QR-01-01-16-P04->QR-01-01-16-P05',
      '02-06-07-P03-S02->02-06-07-P03-S03',
      '02-02-03-P04->02-02-03-P05',
    ]

    const unmatchedSoftRecommendations = l5UnmatchedStableEdges.filter((stableEdge) => softRecommendationEdges.includes(stableEdge))
    expect(unmatchedSoftRecommendations, 'curated soft sequence recommendations remain visible through the L2 resolver, but they must no longer keep the L5 unmatched governance queue open')
      .toHaveLength(0)

    for (const stableEdge of softRecommendationEdges) {
      const [predecessorStableCode, successorStableCode] = stableEdge.split('->')
      const predecessorNode = chinaNodes.find((node) => node.stableCode === predecessorStableCode)
        ?? domainNodes.find((node) => node.stableCode === predecessorStableCode)
      const successorNode = chinaNodes.find((node) => node.stableCode === successorStableCode)
        ?? domainNodes.find((node) => node.stableCode === successorStableCode)
      const catalogSource = chinaNodes.some((node) => node.stableCode === predecessorStableCode)
        ? 'china_gb50300_template_catalog'
        : 'domain_wbs_template_catalog'

      expect(predecessorNode, `${predecessorStableCode} must resolve to a catalog node`).toBeTruthy()
      expect(successorNode, `${successorStableCode} must resolve to a catalog node`).toBeTruthy()

      const resolved = resolveStandardInternalFlowRule({
        predecessorStableCode,
        predecessorName: predecessorNode!.name,
        successorStableCode,
        successorName: successorNode!.name,
        successorCategoryType: successorNode!.categoryType,
        catalogSource,
      })

      expect(resolved.curationStatus, `${stableEdge} must stay curated guidance`).toBe('curated')
      expect(resolved.curationMethod, `${stableEdge} curation method`).toBe('manual_registry')
      expect(resolved.relationKind, `${stableEdge} must stay a soft sequence`).toBe('soft_sequence')
      expect(resolved.createsDependency, `${stableEdge} must not create runtime dependencies`).toBe(false)
      expect(resolved.reviewNeeded, `${stableEdge} should not need broad review; it is intentionally soft`).toBe(false)
    }
    expect(report.runtimeMetrics.cross_item_workflow.zeroMatchRuleCount).toBe(0)
    expect(report.runtimeMetrics.process_constraint.keywordFallbackMatchedEdgeCount).toBe(0)
  })

