  it('requires L5 electrical conduit installation facts before plaster, ceiling, wall, and public-room finish closure', () => {
    const report = collectConstructionDependencyRuleSystemReport(20000)
    const processConstraintCoverage = report.runtimeMetrics.process_constraint.coverage
    const processConstraintBackValidation = report.processConstraintBackValidation
    const roughInRule = crossRule('mep_rough_in_to_ceiling_wall_close') as ReturnType<typeof crossRule> & { excludedPredecessorCodePrefixes?: string[] }
    const publicRoomRule = crossRule('mep_rough_in_to_public_room_finish_close') as ReturnType<typeof crossRule> & { excludedPredecessorCodePrefixes?: string[] }
    const predecessorPrefixes = ['07-05-03', '07-06-05']
    const scenarios: Array<{
      ruleCode: string
      successorPrefixes: string[]
      expectedEffectId: string
      requiredMethodVariants: string[]
    }> = [
      {
        ruleCode: 'electrical_conduit_installation_to_plaster_base_closure_release_gate',
        successorPrefixes: ['03-02', '03-02-01', '03-02-02', '03-02-03'],
        expectedEffectId: 'electrical-conduit-installation-plaster-base-closure-project-fact-gate',
        requiredMethodVariants: ['electrical_conduit_installation', 'lighting_conduit_installation', 'standby_power_conduit_installation', 'wall_slot_closure_review', 'plaster_base_before_finish', 'concealed_interface_release'],
      },
      {
        ruleCode: 'electrical_conduit_installation_to_clear_masonry_pointing_release_gate',
        successorPrefixes: ['03-02-04'],
        expectedEffectId: 'electrical-conduit-installation-clear-masonry-pointing-project-fact-gate',
        requiredMethodVariants: ['electrical_conduit_installation', 'lighting_conduit_installation', 'standby_power_conduit_installation', 'clear_masonry_pointing_release', 'concealed_interface_release'],
      },
      {
        ruleCode: 'electrical_conduit_installation_to_ceiling_closure_release_gate',
        successorPrefixes: ['03-05', '03-05-01', '03-05-02', '03-05-03', 'DEC-02-01', 'DEC-02-01-01'],
        expectedEffectId: 'electrical-conduit-installation-ceiling-closure-project-fact-gate',
        requiredMethodVariants: ['electrical_conduit_installation', 'lighting_conduit_installation', 'standby_power_conduit_installation', 'ceiling_closure_before_finish', 'concealed_interface_release'],
      },
      {
        ruleCode: 'electrical_conduit_installation_to_wall_veneer_finish_release_gate',
        successorPrefixes: ['DEC-02-01-02', 'DEC-02-01-03'],
        expectedEffectId: 'electrical-conduit-installation-wall-veneer-finish-project-fact-gate',
        requiredMethodVariants: ['electrical_conduit_installation', 'lighting_conduit_installation', 'standby_power_conduit_installation', 'wall_slot_closure_review', 'wall_veneer_finish_release', 'concealed_interface_release'],
      },
      {
        ruleCode: 'electrical_conduit_installation_to_public_room_finish_release_gate',
        successorPrefixes: ['DEC-05-01', 'DEC-05-01-01', 'DEC-05-01-02'],
        expectedEffectId: 'electrical-conduit-installation-public-room-finish-project-fact-gate',
        requiredMethodVariants: ['electrical_conduit_installation', 'lighting_conduit_installation', 'standby_power_conduit_installation', 'public_room_finish_release', 'concealed_interface_release'],
      },
    ]

    expect(roughInRule.excludedPredecessorCodePrefixes, 'interior lighting and standby-power conduit installation must remain a true rough-in to finish-closure carrier')
      .not.toEqual(expect.arrayContaining(predecessorPrefixes))
    expect(publicRoomRule.excludedPredecessorCodePrefixes, 'interior lighting and standby-power conduit installation must remain a true rough-in to public-room finish carrier')
      .not.toEqual(expect.arrayContaining(predecessorPrefixes))

    for (const scenario of scenarios) {
      const rule = constraintRule(scenario.ruleCode)
      const expectedStableEdges = predecessorPrefixes.flatMap((predecessorCode) => (
        scenario.successorPrefixes.map((successorCode) => `${predecessorCode}->${successorCode}`)
      ))
      const matchedRuntimeRows = report.processConstraintCoverage.matchedPairsByRuleCode[rule.stableCode] ?? []
      const matchedRuntimeStableEdges = Array.from(new Set(
        matchedRuntimeRows.flatMap((pair) => pair.exampleStableCodes),
      ))
      const stillUnmatchedTargetPairs = processConstraintBackValidation.topUnmatchedExistingRelationEdges
        .flatMap((pair) => pair.exampleStableCodes)
        .filter((stableEdge) => expectedStableEdges.includes(stableEdge))
      const projectFactEffects = rule.conditionalEffects.filter((effect) => effect.effect === 'require_project_fact_gate')
      const methodVariantValues = projectFactEffects.flatMap((effect) => (
        effect.when
          .filter((condition) => condition.field === 'method_variant_code')
          .flatMap((condition) => condition.values)
      ))

      expect(processConstraintCoverage.byMatchedRuleCode[rule.stableCode] ?? 0, `${rule.stableCode} must match only the exact electrical conduit installation finish-closure target edges`)
        .toBe(expectedStableEdges.length)
      expect(matchedRuntimeStableEdges.sort(), `${rule.stableCode} must cover exactly the structured stable-code target edges`)
        .toEqual(expectedStableEdges.sort())
      expect(matchedRuntimeRows.every((pair) => (pair.matchQualities.structured_code ?? 0) === pair.count))
        .toBe(true)
      expect(stillUnmatchedTargetPairs, `${rule.stableCode} target edges should leave the unmatched backlog`)
        .toHaveLength(0)
      expect(rule.standardCatalogCodePrefixes).toEqual(expect.arrayContaining([
        ...predecessorPrefixes,
        ...scenario.successorPrefixes,
      ]))
      expect(rule.templateNodeStableCodePrefixes).toEqual(expect.arrayContaining([
        ...predecessorPrefixes,
        ...scenario.successorPrefixes,
      ]))
      expect(rule.standardCatalogCodePrefixes).not.toEqual(expect.arrayContaining([
        '07-01-04',
        '07-05-04',
        '07-06-07',
      ]))
      expect(rule.requiredKeywordGroups[0]).toEqual(predecessorPrefixes)
      expect(rule.requiredKeywordGroups[1]).toEqual(scenario.successorPrefixes)
      expect(rule.applicationMode).toBe('gate_wait')
      expect(rule.relationshipScope).toBe('cross_scope_edge')
      expect(rule.supportedRelationKinds).toEqual(['explicit_task_dependency'])
      expect(rule.impactMode).toBe('confidence_only')
      expect(rule.runtimeActionPolicy).toBe('confidence_only')
      expect(rule.timeSourcePolicy).toBe('project_fact_then_standard_work_duration')
      expect(rule.durationAuthorityPolicy).toBe('no_duration_values_in_process_constraint')
      expect(rule.dependencyCreationPolicy).toBe('never_create_dependency')
      expect(rule.relationInputPolicy).toBe('requires_existing_relation')
      expect(rule.durationDoubleCountPolicy).toBe('standard_work_duration_owns_all_day_values_process_constraint_owns_edge_routing')
      expect(projectFactEffects.map((effect) => effect.id)).toContain(scenario.expectedEffectId)
      expect(methodVariantValues).toEqual(expect.arrayContaining(scenario.requiredMethodVariants))
      expect(projectFactEffects.every((effect) => (effect.evidenceSourceKeys?.length ?? 0) > 0)).toBe(true)
      expect(projectFactEffects.every((effect) => effect.quantityEvidenceRequirement === 'not_applicable')).toBe(true)
    }

    expect(report.runtimeMetrics.cross_item_workflow.zeroMatchRuleCount).toBe(0)
    expect(processConstraintCoverage.keywordFallbackMatchedEdgeCount).toBe(0)
    expect(processConstraintCoverage.structuredCodeMatchedEdgeCount)
      .toBe(processConstraintCoverage.processConstraintMatchedEdgeCount)
  })

  it('keeps intelligent equipment-software installation out of plaster carriers while preserving exact finish L5 gates', () => {
    const equipmentSoftwarePrefixes = [
      '08-08-03',
      '08-09-03',
      '08-10-03',
      '08-12-03',
      '08-13-03',
    ]
    const plasterFalseSuccessors = [
      '03-02',
      '03-02-01',
      '03-02-02',
      '03-02-03',
      '03-02-04',
    ]
    const ceilingWallSuccessors = [
      '03-05',
      '03-05-01',
      '03-05-02',
      '03-05-03',
      'DEC-02-01',
      'DEC-02-01-01',
      'DEC-02-01-02',
      'DEC-02-01-03',
    ]
    const publicRoomSuccessors = ['DEC-05-01', 'DEC-05-01-01', 'DEC-05-01-02']
    const report = collectConstructionDependencyRuleSystemReport(20000)
    const roughInRule = crossRule('mep_rough_in_to_ceiling_wall_close') as ReturnType<typeof crossRule> & { excludedPredecessorCodePrefixes?: string[] }
    const exactCeilingWallRule = crossRule('intelligent_equipment_software_installation_to_exact_ceiling_wall_finish_edges')
    const ceilingRule = constraintRule('intelligent_equipment_software_installation_to_ceiling_closure_release_gate')
    const wallRule = constraintRule('intelligent_equipment_software_installation_to_wall_veneer_finish_release_gate')
    const publicRoomRule = constraintRule('intelligent_equipment_software_installation_to_public_room_finish_release_gate')
    const forbiddenPlasterEdges = new Set(
      equipmentSoftwarePrefixes.flatMap((predecessorCode) => (
        plasterFalseSuccessors.map((successorCode) => `${predecessorCode}->${successorCode}`)
      )),
    )
    const unmatchedForbiddenPlasterEdges = report.processConstraintBackValidation.topUnmatchedExistingRelationEdges
      .flatMap((pair) => pair.exampleStableCodes)
      .filter((stableEdge) => forbiddenPlasterEdges.has(stableEdge))
    const expectedCeilingWallEdges = equipmentSoftwarePrefixes.flatMap((predecessorCode) => (
      ceilingWallSuccessors.map((successorCode) => `${predecessorCode}->${successorCode}`)
    ))
    const expectedPublicRoomEdges = equipmentSoftwarePrefixes.flatMap((predecessorCode) => (
      publicRoomSuccessors.map((successorCode) => `${predecessorCode}->${successorCode}`)
    ))
    const matchedCeilingEdges = new Set(
      (report.processConstraintCoverage.matchedPairsByRuleCode[ceilingRule.stableCode] ?? [])
        .flatMap((pair) => pair.exampleStableCodes),
    )
    const matchedWallEdges = new Set(
      (report.processConstraintCoverage.matchedPairsByRuleCode[wallRule.stableCode] ?? [])
        .flatMap((pair) => pair.exampleStableCodes),
    )
    const matchedPublicRoomEdges = new Set(
      (report.processConstraintCoverage.matchedPairsByRuleCode[publicRoomRule.stableCode] ?? [])
        .flatMap((pair) => pair.exampleStableCodes),
    )

    expect(unmatchedForbiddenPlasterEdges, 'L3 must not create intelligent equipment/software installation to plaster parent or child carriers for L5 to back-validate')
      .toHaveLength(0)
    expect(roughInRule.excludedPredecessorCodePrefixes, 'broad MEP rough-in L3 rule must exclude intelligent equipment/software installation from plaster-bearing finish carriers')
      .toEqual(expect.arrayContaining(equipmentSoftwarePrefixes))
    expect(exactCeilingWallRule.predecessorCodePrefixes)
      .toEqual(equipmentSoftwarePrefixes)
    expect(exactCeilingWallRule.successorCodePrefixes)
      .toEqual(['03-05', 'DEC-02-01'])
    expect(report.runtimeMetrics.process_constraint.coverage.byMatchedRuleCode[ceilingRule.stableCode] ?? 0)
      .toBe(30)
    expect(report.runtimeMetrics.process_constraint.coverage.byMatchedRuleCode[wallRule.stableCode] ?? 0)
      .toBe(10)
    expect(report.runtimeMetrics.process_constraint.coverage.byMatchedRuleCode[publicRoomRule.stableCode] ?? 0)
      .toBe(15)
    for (const stableEdge of expectedCeilingWallEdges) {
      if (stableEdge.includes('DEC-02-01-02') || stableEdge.includes('DEC-02-01-03')) {
        expect(matchedWallEdges.has(stableEdge), `${wallRule.stableCode} must keep ${stableEdge}`)
          .toBe(true)
      } else {
        expect(matchedCeilingEdges.has(stableEdge), `${ceilingRule.stableCode} must keep ${stableEdge}`)
          .toBe(true)
      }
    }
    for (const stableEdge of expectedPublicRoomEdges) {
      expect(matchedPublicRoomEdges.has(stableEdge), `${publicRoomRule.stableCode} must keep ${stableEdge}`)
        .toBe(true)
    }
    expect(report.runtimeMetrics.cross_item_workflow.zeroMatchRuleCount).toBe(0)
    expect(report.runtimeMetrics.process_constraint.keywordFallbackMatchedEdgeCount).toBe(0)
    expect(report.runtimeMetrics.process_constraint.coverage.structuredCodeMatchedEdgeCount)
      .toBe(report.runtimeMetrics.process_constraint.coverage.processConstraintMatchedEdgeCount)
  })

