  it('keeps foundation-to-underground-waterproof package carriers in confirmed L3 instead of the L5 backlog', () => {
    const report = collectConstructionDependencyRuleSystemReport(20000)
    const l3Rule = crossRule('foundation_to_underground_waterproof')
    const foundationWaterproofEdges = [
      '01-02-03->01-07',
      '01-02-03->01-07-01',
      '01-02-03->01-07-02',
      '01-02-03->01-07-03',
      '01-02-03->01-07-04',
      '01-02-03->01-07-05',
      '01-02-03->WPI-01-01-01',
      '01-02-13->01-07',
      '01-02-13->01-07-01',
      '01-02-13->01-07-02',
      '01-02-13->01-07-03',
      '01-02-13->01-07-04',
      '01-02-13->01-07-05',
      '01-02-13->WPI-01-01-01',
    ] as const
    const l5UnmatchedStableEdges = report.processConstraintBackValidation.topUnmatchedExistingRelationEdges
      .flatMap((pair) => pair.exampleStableCodes)

    expect(l3Rule.strength).toBe('hard')
    expect(l3Rule.autoApplyPolicy).toBe('confirmed_template_only')
    expect(l3Rule.handoffCategory).toBe('underground_waterproof_backfill')
    expect(l3Rule.lagDays, 'foundation to underground waterproof handoff must not be collapsed into same-day L5 fact coverage')
      .toBeGreaterThan(0)
    for (const stableEdge of foundationWaterproofEdges) {
      const [predecessorStableCode, successorStableCode] = stableEdge.split('->') as [string, string]
      expect(rulePrefixesCoverStableCode(l3Rule.predecessorCodePrefixes, predecessorStableCode)).toBe(true)
      expect(rulePrefixesCoverStableCode(l3Rule.successorCodePrefixes, successorStableCode)).toBe(true)
    }
    expect(l5UnmatchedStableEdges.filter((stableEdge) => foundationWaterproofEdges.includes(stableEdge as typeof foundationWaterproofEdges[number])), 'foundation-to-underground-waterproof handoffs are confirmed L3 carriers and must not remain in L5 back-validation')
      .toHaveLength(0)
    expect(report.processConstraintBackValidation.queueSummary.l3ConfirmedParentCarrierExcludedEdgeCount)
      .toBeGreaterThanOrEqual(foundationWaterproofEdges.length)
  })

