    expect(cleanroomProcessRule.autoApplyPolicy).toBe('confirmed_template_only')
    expect(dataCenterProcessRule.boundaryPolicy).toMatch(/process|data|hall|envelope|cooling|commissioning|project facts|duration/i)
    expect(cleanroomProcessRule.boundaryPolicy).toMatch(/process|clean|zone|handoff|commissioning|project facts|duration/i)
