  it('keeps L2-owned wall sanding clean to sample confirmation gates out of the L5 unmatched back-validation queue', () => {
    const report = collectConstructionDependencyRuleSystemReport(20000)
    const sandingToSampleEdges = [
      '03-10-01-P04->03-10-01-P05',
      '03-10-02-P04->03-10-02-P05',
      '03-10-03-P04->03-10-03-P05',
    ]
    const catalogNodesByStableCode = new Map(
      flattenChinaTemplateCatalog().map((node) => [node.stableCode, node]),
    )
    const l5UnmatchedStableEdges = report.processConstraintBackValidation.topUnmatchedExistingRelationEdges
      .flatMap((pair) => pair.exampleStableCodes)

    for (const stableEdge of sandingToSampleEdges) {
      const [predecessorStableCode, successorStableCode] = stableEdge.split('->')
      const predecessorNode = catalogNodesByStableCode.get(predecessorStableCode)
      const successorNode = catalogNodesByStableCode.get(successorStableCode)
      expect(predecessorNode, `${predecessorStableCode} should exist in china template catalog`).toBeTruthy()
      expect(successorNode, `${successorStableCode} should exist in china template catalog`).toBeTruthy()
      const l2Rule = resolveStandardInternalFlowRule({
        predecessorStableCode,
        predecessorName: predecessorNode!.name,
        successorStableCode,
        successorName: successorNode!.name,
        successorCategoryType: successorNode!.categoryType,
      })

      expect(l2Rule.seedRuleId).toContain('wall-sanding-clean-to-sample-confirm')
      expect(l2Rule.curationStatus).toBe('curated')
      expect(l2Rule.relationKind).toBe('acceptance_gate')
      expect(l2Rule.createsDependency).toBe(true)
      expect(l2Rule.scope).toBe('same_parent')
      expect(l2Rule.evidenceRefs.map((ref) => ref.rationale ?? '').join(' '))
        .toMatch(/打磨清理|样板确认|完成面/)
    }

    expect(l5UnmatchedStableEdges.filter((stableEdge) => sandingToSampleEdges.includes(stableEdge)), 'L5 back-validation must not ask process_constraint to cover L2-owned wall sanding sample-confirm gates')
      .toHaveLength(0)
  })

