    expect(rule.timeSourcePolicy).toBe('project_fact_then_standard_work_duration')
    expect(rule.relationInputPolicy).toBe('requires_existing_relation')
    expect(rule.dependencyCreationPolicy).toBe('never_create_dependency')
    expect(rule.durationAuthorityPolicy).toBe('no_duration_values_in_process_constraint')
    expect(rule.quantityEvidenceRequirement).toBe('not_applicable')
    expect(rule.applicableCatalogGroups).toEqual(['specialty'])
    expect(rule.applicableDurationContributionModes).toEqual(['duration_bearing', 'quality_gate'])
    expect(rule.relationshipScope).toBe('cross_scope_edge')
    expect(rule.supportedRelationKinds).toEqual(['explicit_task_dependency'])
    expect(rule.standardCatalogCodePrefixes).toEqual(['BDT-01-01-05-P10', 'BDT-01-01-06-P01', 'BDT-01-01-06-P04'])
    expect(rule.templateNodeStableCodePrefixes).toEqual(['BDT-01-01-05-P10', 'BDT-01-01-06-P01', 'BDT-01-01-06-P04'])
    expect(rule.boundaryPolicyNotes.join(' ')).toMatch(/existing|cross-item|basement|MEP|workface|equipment-room|floor-base|project fact/i)
    expect(rule.boundaryPolicyNotes.join(' ')).toMatch(/not.*garage floor|not.*archive|not.*delivery|not.*occupancy|not.*statutory/i)
    expect(rule.excludedKeywordTerms).toEqual(expect.arrayContaining([
      'DEC-02-02-02-P02',
      'archive',
      'delivery',
      'occupancy',
      'statutory acceptance',
      'municipal mainline',
      'grid',
    ]))

    expect(effect).toBeTruthy()
    expect(effect!.quantityEvidenceRequirement).toBe('not_applicable')
    expect(effect!.quantityProxyRiskLevel).toBe('not_applicable')
    expect(effect!.when).toEqual(expect.arrayContaining([
      expect.objectContaining({
        field: 'project_type_code',
        operator: 'includes_any',
        values: expect.arrayContaining(['commercial', 'complex_building', 'basement', 'residential']),
      }),
      expect.objectContaining({
        field: 'method_variant_code',
        operator: 'includes_any',
        values: expect.arrayContaining([
          'basement_mep_workface_handover',
          'equipment_room_interface_review',
          'floor_base_preparation',
          'finish_access_release',
        ]),
      }),
    ]))
    expect(effect!.evidenceSourceKeys).toEqual(expect.arrayContaining(['GB50300_2013', 'GB50242_2018', 'GB50303_2015', 'GB50243_2016']))

    expect(processConstraintCoverage.byMatchedRuleCode.basement_mep_workface_handover_to_equipment_room_floor_base_project_fact_gate ?? 0)
      .toBe(2)
    const targetPairs = report.processConstraintCoverage.matchedPairsByRuleCode
      .basement_mep_workface_handover_to_equipment_room_floor_base_project_fact_gate
      ?? []
    const matchedStableEdges = targetPairs.flatMap((pair) => pair.exampleStableCodes)
    expect(matchedStableEdges).toEqual(expect.arrayContaining(targetCases.map((target) => target.edge)))
    expect(targetPairs).toHaveLength(2)
