  it('splits outdoor municipal pipe-test road restoration into exact L3 leaves and L5 fact gates', () => {
    const report = collectConstructionDependencyRuleSystemReport(20000)
    const pipeTestPrefixes = ['05-06-03', '05-07-03', '05-08-06']
    const broadRoadParentSuccessors = ['OUT-01', 'OUT-01-01']
    const exactRoadRestoreSuccessors = ['OUT-01-01-01', 'OUT-04-01-01']
    const forbiddenParentEdges = new Set(
      pipeTestPrefixes.flatMap((predecessorCode) => (
        broadRoadParentSuccessors.map((successorCode) => `${predecessorCode}->${successorCode}`)
      )),
    )
    const exactLeafEdges = exactRoadRestoreSuccessors.flatMap((successorCode) => (
      pipeTestPrefixes.map((predecessorCode) => `${predecessorCode}->${successorCode}`)
    ))
    const topUnmatchedEdges = report.processConstraintBackValidation.topUnmatchedExistingRelationEdges
      .flatMap((pair) => pair.exampleStableCodes)
    const unmatchedParentEdges = topUnmatchedEdges.filter((stableEdge) => forbiddenParentEdges.has(stableEdge))
    const roadRestoreRule = crossRule('outdoor_pipe_backfill_to_road_restore')
    const municipalReleaseRule = crossRule('municipal_pipe_test_to_road_restore_release')
    const l5Gate = constraintRule('municipal_pipe_test_to_exact_road_paving_restore_release_gate')

    expect(unmatchedParentEdges, 'L3 must not create direct runtime carriers from municipal pipe tests to broad OUT-01 or OUT-01-01 rollup road packages')
      .toHaveLength(0)
    expect(roadRestoreRule.successorCodePrefixes, 'outdoor pipe backfill release must target exact road/paving restoration leaves')
      .toEqual(expect.arrayContaining(exactRoadRestoreSuccessors))
    expect(roadRestoreRule.successorCodePrefixes)
      .not.toEqual(expect.arrayContaining(broadRoadParentSuccessors))
    expect(municipalReleaseRule.successorCodePrefixes, 'municipal pipe test release must target exact road/paving restoration leaves')
      .toEqual(expect.arrayContaining(exactRoadRestoreSuccessors))
    expect(municipalReleaseRule.successorCodePrefixes)
      .not.toEqual(expect.arrayContaining(broadRoadParentSuccessors))
    expect(l5Gate.standardCatalogCodePrefixes)
      .toEqual(expect.arrayContaining([...pipeTestPrefixes, ...exactRoadRestoreSuccessors]))
    expect(l5Gate.templateNodeStableCodePrefixes)
      .toEqual(expect.arrayContaining([...pipeTestPrefixes, ...exactRoadRestoreSuccessors]))
    expect(l5Gate.relationshipScope).toBe('cross_scope_edge')
    expect(l5Gate.relationInputPolicy).toBe('requires_existing_relation')
    expect(l5Gate.dependencyCreationPolicy).toBe('never_create_dependency')
    expect(l5Gate.boundaryPolicyNotes.join(' '))
      .toMatch(/existing|OUT-01-01-01|OUT-04-01-01|not.*OUT-01|not.*standalone/i)
    expect(report.processConstraintCoverage.matchedPairsByRuleCode[l5Gate.stableCode]?.flatMap((pair) => pair.exampleStableCodes))
      .toEqual(expect.arrayContaining(exactLeafEdges))
    expect(report.runtimeMetrics.cross_item_workflow.zeroMatchRuleCount).toBe(0)
    expect(report.runtimeMetrics.process_constraint.keywordFallbackMatchedEdgeCount).toBe(0)
  })

  it('requires L5 municipal pipe-test facts before TOD commercial municipal interface release on existing L3 carriers', () => {
    const report = collectConstructionDependencyRuleSystemReport(20000)
    const processConstraintCoverage = report.runtimeMetrics.process_constraint.coverage
    const rule = constraintRule('municipal_pipe_test_to_tod_commercial_interface_release_gate')
    const l3Carrier = crossRule('municipal_pipe_test_to_road_restore_release')
    const expectedStableEdges = [
      '05-06-03->TOD-03-01-01',
      '05-07-03->TOD-03-01-01',
      '05-08-06->TOD-03-01-01',
    ].sort()
    const stillUnmatchedTargetPairs = report.processConstraintBackValidation.topUnmatchedExistingRelationEdges
      .flatMap((pair) => pair.exampleStableCodes)
      .filter((stableEdge) => expectedStableEdges.includes(stableEdge))
    const matchedRuntimeRows = report.processConstraintCoverage.matchedPairsByRuleCode[rule.stableCode] ?? []
    const matchedRuntimeStableEdges = Array.from(new Set(
      matchedRuntimeRows.flatMap((pair) => pair.exampleStableCodes),
    )).sort()
    const projectFactEffects = rule.conditionalEffects.filter((effect) => effect.effect === 'require_project_fact_gate')
    const conditionFields = projectFactEffects.flatMap((effect) => effect.when.map((condition) => condition.field))

    expect(l3Carrier.successorCodePrefixes, 'L3 owns the existing TOD commercial municipal interface carrier; L5 only gates facts after the edge exists')
      .toEqual(expect.arrayContaining(['TOD-03-01-01']))
    expect(l3Carrier.boundaryPolicy)
      .toMatch(/TOD|commercial|municipal interface|station-city|commercial-entry/i)
    expect(processConstraintCoverage.byMatchedRuleCode[rule.stableCode] ?? 0, `${rule.stableCode} must match the existing municipal pipe-test to TOD commercial-interface carrier edges`)
      .toBe(expectedStableEdges.length)
    expect(matchedRuntimeStableEdges).toEqual(expectedStableEdges)
    expect(matchedRuntimeRows.every((pair) => pair.matchQualities.structured_code === pair.count))
      .toBe(true)
    expect(stillUnmatchedTargetPairs, `${rule.stableCode} target TOD interface carrier edges should leave the unmatched backlog`)
      .toHaveLength(0)
    expect(rule.applicationMode).toBe('gate_wait')
    expect(rule.constraintType).toBe('municipal_connection_wait')
    expect(rule.relationshipScope).toBe('cross_scope_edge')
    expect(rule.supportedRelationKinds).toEqual(['explicit_task_dependency'])
    expect(rule.impactMode).toBe('confidence_only')
    expect(rule.runtimeActionPolicy).toBe('confidence_only')
    expect(rule.timeSourcePolicy).toBe('project_fact_then_standard_work_duration')
    expect(rule.durationAuthorityPolicy).toBe('no_duration_values_in_process_constraint')
    expect(rule.dependencyCreationPolicy).toBe('never_create_dependency')
    expect(rule.relationInputPolicy).toBe('requires_existing_relation')
    expect(rule.standardCatalogCodePrefixes).toEqual([
      '05-06-03',
      '05-07-03',
      '05-08-06',
      'TOD-03-01-01',
    ])
    expect(rule.templateNodeStableCodePrefixes).toEqual([
      '05-06-03',
      '05-07-03',
      '05-08-06',
      'TOD-03-01-01',
    ])
    expect(rule.standardCatalogCodePrefixes).not.toEqual(expect.arrayContaining([
      '05',
      '05-',
      '05-06',
      '05-07',
      '05-08',
      'OUT',
      'MUN',
      'TOD',
      'TOD-03',
      'TOD-03-01',
    ]))
    expect(projectFactEffects.map((effect) => effect.id))
      .toContain('municipal-pipe-test-tod-commercial-interface-project-fact-gate')
    expect(conditionFields).toEqual(expect.arrayContaining(['project_type_code', 'municipal_connection_status', 'method_variant_code']))
    expect(projectFactEffects.every((effect) => (effect.evidenceSourceKeys?.length ?? 0) > 0)).toBe(true)
    expect(projectFactEffects.every((effect) => effect.quantityEvidenceRequirement === 'not_applicable')).toBe(true)
    expect(rule.boundaryPolicyNotes.join(' '))
      .toMatch(/existing.*05-06-03.*05-07-03.*05-08-06.*TOD-03-01-01/i)
    expect(rule.boundaryPolicyNotes.join(' '))
      .toMatch(/not.*standalone|not.*road|not.*bridge|not.*tunnel|not.*railway|not.*airport|not.*port|not.*energy|not.*grid/i)
    expect(rule.boundaryPolicyNotes.join(' '))
      .toMatch(/never creates dependencies|never create dependencies|never creates dependency/i)
    expect(rule.boundaryPolicyNotes.join(' '))
      .toMatch(/never stores.*day|no.*day values/i)
    expect(processConstraintCoverage.keywordFallbackMatchedEdgeCount).toBe(0)
    expect(processConstraintCoverage.structuredCodeMatchedEdgeCount).toBe(processConstraintCoverage.processConstraintMatchedEdgeCount)
  })

