  it('keeps confirmed foundation pit base handover to cap-raft cushion exact L3 handoff out of the L5 unmatched back-validation queue', () => {
    const targetStableEdge = 'FND-02-01-02-P12->01-02-03-P02'
    const rule = crossRule('foundation_pit_base_handover_to_cap_raft_cushion_process')
    const report = collectConstructionDependencyRuleSystemReport(20000)
    const l5UnmatchedStableEdges = report.processConstraintBackValidation.topUnmatchedExistingRelationEdges
      .flatMap((pair) => pair.exampleStableCodes)

    expect(rule.predecessorCodePrefixes).toEqual(['FND-02-01-02-P12'])
    expect(rule.successorCodePrefixes).toEqual(['01-02-03-P02'])
    expect(rule.autoApplyPolicy).toBe('confirmed_template_only')
    expect(rule.strength).toBe('hard')
    expect(rule.handoffCategory).toBe('foundation_deep_basement')
    expect(l5UnmatchedStableEdges, `${targetStableEdge} is a confirmed exact L3 foundation handoff and must not remain in the L5 unmatched back-validation queue`)
      .not.toContain(targetStableEdge)

    expect(report.runtimeMetrics.process_constraint.keywordFallbackMatchedEdgeCount).toBe(0)
    expect(report.runtimeMetrics.cross_item_workflow.zeroMatchRuleCount).toBe(0)
  })

