  it('reports L3 candidate and manual-confirm families as project-fact governance queues instead of hardening backlog', () => {
    const report = collectConstructionDependencyRuleSystemReport(100)
    const l3LagCalibrationAudit = (
      report.dependencySystemCloseout.trustHardening as typeof report.dependencySystemCloseout.trustHardening & {
        l3LagCalibrationAudit?: {
          candidateManualConfirmFamilyAudit?: {
            status: string
            familyCount: number
            manualConfirmRuleCount: number
            candidateRuleCount: number
            runtimeEligibleRuleCount: number
            candidateAndManualConfirmAreRuntimeBlocked: boolean
            families: Array<{
              handoffCategory: string
              totalRuleCount: number
              manualConfirmRuleCount: number
              candidateRuleCount: number
              candidateManualRatio: number
              runtimeEligibleRuleCount: number
              governanceReason: string
              promotionPolicy: string
            }>
          }
        }
      }
    ).l3LagCalibrationAudit

    expect(l3LagCalibrationAudit).toBeTruthy()
    const governanceAudit = l3LagCalibrationAudit!.candidateManualConfirmFamilyAudit

    expect(governanceAudit).toEqual(expect.objectContaining({
      status: 'candidate_manual_confirm_requires_project_fact_governance',
      candidateAndManualConfirmAreRuntimeBlocked: true,
    }))
    expect(governanceAudit!.familyCount).toBeGreaterThanOrEqual(3)
    expect(governanceAudit!.manualConfirmRuleCount).toBeGreaterThanOrEqual(5)
    expect(governanceAudit!.candidateRuleCount).toBeGreaterThanOrEqual(5)
    expect(governanceAudit!.runtimeEligibleRuleCount).toBe(0)

    const familyNames = governanceAudit!.families.map((family) => family.handoffCategory)
    expect(familyNames).toEqual(expect.arrayContaining([
      'hotel_factory_unit',
      'data_center_cleanroom',
      'outdoor_municipal',
    ]))

    for (const family of governanceAudit!.families) {
      expect(family.candidateManualRatio).toBeGreaterThan(0)
      expect(family.runtimeEligibleRuleCount).toBe(0)
      expect(family.governanceReason).toMatch(/project|fact|operator|validation|calendar|scope|manual|candidate|governance/i)
      expect(family.promotionPolicy).toMatch(/replay|approval|manual|evidence|confirmed/i)
    }
  })

