  it('surfaces high-priority dormant L4 statutory completion gates as backend replay queue instead of pretending runtime coverage', () => {
    const report = collectConstructionDependencyRuleSystemReport(120)
    const l4Audit = report.dependencySystemCloseout.trustHardening.l4DependencyIntentAudit as typeof report.dependencySystemCloseout.trustHardening.l4DependencyIntentAudit & {
      explicitGateDormantTemplateCount?: number
      explicitGateDormantTemplateCodes?: string[]
      highPriorityDormantTemplateCount?: number
      highPriorityDormantTemplateCodes?: string[]
      highPriorityDormantEvidenceGapCount?: number
      explicitGateAcceptanceTimelineObservedTemplateCodes?: string[]
      dormantTemplatePolicy?: string
      highPriorityDormantTemplateQueue?: Array<{
        templateCode: string
        sampleFromReferencedCode: string
        sampleToReferencedCode: string
        lagDays: number
        scopeRule: string
        reasonCode: string
        priority: string
        backendOnly: boolean
        runtimeEligible: boolean
        replayEvidenceRequired: string[]
        promotionPolicy: string
        blockingPolicy: string
      }>
      highPriorityDormantEvidenceGapAudit?: {
        status: string
        backendOnly: boolean
        directEvidenceRequired: boolean
        gapCount: number
        blockedObservationTemplateCodes: string[]
        evidenceGapItems: Array<{
          templateCode: string
          directEvidenceStatus: string
          blockedObservation: boolean
          unsupportedNearbyEvidence: string[]
          requiredDirectEvidence: string[]
        }>
      }
    }
    const newlyObservedStatutoryCompletionGateCodes = [
      'completion_acceptance_to_owner_delivery_release',
      'completion_acceptance_to_occupancy_use_release',
      'public_assembly_fire_safety_check_to_opening_release',
    ]
    const acceptanceTimelineObservedStatutoryGateCodes = [
      'quality_supervision_report_to_completion_filing',
      'completion_filing_to_delivery_filing_release',
      'delivery_filing_to_owner_delivery_release',
      'sanitation_facility_acceptance_to_delivery_filing_release',
      'archive_acceptance_to_completion_filing_release',
      'comprehensive_acceptance_to_completion_filing_release',
      'property_handover_inspection_to_delivery_filing_release',
      'household_acceptance_to_delivery_filing_release',
    ]

    expect(l4Audit.explicitGateDormantTemplateCodes).not.toEqual(expect.arrayContaining(newlyObservedStatutoryCompletionGateCodes))
    expect(l4Audit.explicitGateDormantTemplateCodes).not.toEqual(expect.arrayContaining(acceptanceTimelineObservedStatutoryGateCodes))
    expect(l4Audit.explicitGateAcceptanceTimelineObservedTemplateCodes).toEqual(
      expect.arrayContaining([
        ...acceptanceTimelineObservedStatutoryGateCodes,
        ...newlyObservedStatutoryCompletionGateCodes,
      ]),
    )
    expect(l4Audit.dormantTemplatePolicy).toMatch(/verified|unobserved|governance|runtime/i)

    const queue = l4Audit.highPriorityDormantTemplateQueue ?? []
    expect(l4Audit.highPriorityDormantTemplateCount).toBe(queue.length)
    expect(l4Audit.highPriorityDormantTemplateCodes).toEqual(queue.map((item) => item.templateCode).sort())
    expect(queue.map((item) => item.templateCode)).not.toEqual(expect.arrayContaining(newlyObservedStatutoryCompletionGateCodes))
    expect(queue.map((item) => item.templateCode)).not.toEqual(expect.arrayContaining(acceptanceTimelineObservedStatutoryGateCodes))
    for (const templateCode of newlyObservedStatutoryCompletionGateCodes) {
      expect(queue.map((item) => item.templateCode)).not.toContain(templateCode)
    }

    for (const templateCode of newlyObservedStatutoryCompletionGateCodes) {
      expect(l4Audit.explicitGateAcceptanceTimelineObservedTemplateCodes).toContain(templateCode)
      expect(l4Audit.explicitGateObservedTemplateCodes).toContain(templateCode)
    }
    expect(l4Audit.explicitGateRuntimeObservedTemplateCodes).toEqual(expect.arrayContaining([
      'completion_filing_to_occupancy_use_release',
      'completion_filing_to_owner_delivery_release',
      'fire_acceptance_to_occupancy_use_release',
      'household_acceptance_to_delivery_release',
    ]))

    const gapAudit = l4Audit.highPriorityDormantEvidenceGapAudit
    expect(gapAudit).toEqual(expect.objectContaining({
      status: 'high_priority_l4_dormant_direct_evidence_gap_visible',
      backendOnly: true,
      directEvidenceRequired: true,
      gapCount: 0,
    }))
    expect(l4Audit.highPriorityDormantEvidenceGapCount).toBe(gapAudit!.gapCount)
    expect(gapAudit!.gapCount).toBe(queue.length)
    expect(gapAudit!.blockedObservationTemplateCodes).toEqual([])
    expect(gapAudit!.evidenceGapItems).toEqual([])
  })

