  it('matches exact L5 fire linkage retest gates on duration-bearing linkage carriers', () => {
    const report = collectConstructionDependencyRuleSystemReport(20000)
    const processConstraintCoverage = report.runtimeMetrics.process_constraint.coverage
    const targetCases = [
      {
        stableEdge: 'ELE-04-01-01-P06->FIR-03-02-01-P04',
        carrierRuleCode: 'emergency_power_load_transfer_test_to_fire_cross_system_linkage_process',
        ruleCode: 'emergency_power_load_transfer_to_fire_cross_system_linkage_retest_project_fact_gate',
      },
      {
        stableEdge: 'FIR-04-01-01-P08->FIR-03-02-01-P04',
        carrierRuleCode: 'fire_shutter_descent_test_to_shutter_access_elevator_linkage_process',
        ruleCode: 'fire_shutter_descent_to_shutter_access_elevator_linkage_retest_project_fact_gate',
      },
      {
        stableEdge: 'ELV-02-01-02-P05->FIR-03-02-01-P04',
        carrierRuleCode: 'elevator_fire_recall_test_to_fire_access_elevator_linkage_process',
        ruleCode: 'elevator_fire_recall_to_fire_access_elevator_linkage_retest_project_fact_gate',
      },
    ] as const
    const l5UnmatchedStableEdges = report.processConstraintBackValidation.topUnmatchedExistingRelationEdges
      .flatMap((pair) => pair.exampleStableCodes)
    const matchedPairsByStableEdge = new Map(report.processConstraintCoverage.topCrossScopeMatchedPairs
      .flatMap((pair) => pair.exampleStableCodes.map((stableEdge) => [stableEdge, pair] as const)))

    for (const currentCase of targetCases) {
      const l3Rule = crossRule(currentCase.carrierRuleCode)
      const rule = constraintRule(currentCase.ruleCode)
      const matchedPair = matchedPairsByStableEdge.get(currentCase.stableEdge)

      expect(l3Rule.autoApplyPolicy, `${currentCase.stableEdge} must remain an explicit L3 carrier`).toBe('confirmed_template_only')
      expect(l3Rule.strength).toBe('hard')
      expect(rule.relationshipScope, `${currentCase.ruleCode} must only enhance existing cross-scope edges`).toBe('cross_scope_edge')
      expect(rule.relationInputPolicy).toBe('requires_existing_relation')
      expect(rule.dependencyCreationPolicy).toBe('never_create_dependency')
      expect(rule.durationAuthorityPolicy).toBe('no_duration_values_in_process_constraint')
      expect(rule.applicableDurationContributionModes, `${currentCase.ruleCode} must match duration-bearing fire-linkage carriers as L5 fact gates`)
        .toEqual(expect.arrayContaining(['duration_bearing', 'quality_gate']))
      expect(processConstraintCoverage.byMatchedRuleCode[currentCase.ruleCode] ?? 0, `${currentCase.ruleCode} must match the exact current fire-linkage edge`)
        .toBeGreaterThanOrEqual(1)
      expect(matchedPair?.matchedRuleCodes, `${currentCase.stableEdge} must be matched by ${currentCase.ruleCode}`)
        .toEqual(expect.arrayContaining([currentCase.ruleCode]))
      expect(matchedPair?.matchQualities, `${currentCase.stableEdge} must match by structured stable-code, not keyword fallback`)
        .toEqual({ structured_code: 1 })
      expect(l5UnmatchedStableEdges, `${currentCase.stableEdge} is an exact L5 fire-linkage fact gate carrier and must not remain in the L5 unmatched queue`)
        .not.toContain(currentCase.stableEdge)
    }

    expect(report.runtimeMetrics.cross_item_workflow.zeroMatchRuleCount).toBe(0)
    expect(report.runtimeMetrics.process_constraint.keywordFallbackMatchedEdgeCount).toBe(0)
    expect(processConstraintCoverage.structuredCodeMatchedEdgeCount).toBe(processConstraintCoverage.processConstraintMatchedEdgeCount)
  })

