  it('requires L5 MEP commissioning release facts before finish closure on existing cross-scope edges', () => {
    const report = collectConstructionDependencyRuleSystemReport(40)
    const processConstraintCoverage = report.runtimeMetrics.process_constraint.coverage
    const processConstraintBackValidation = report.processConstraintBackValidation
    const matchedRuleCodes = processConstraintCoverage.byMatchedRuleCode
    const rule = constraintRule('mep_system_commissioning_to_finish_closure_release_gate')
    const projectFactEffects = rule.conditionalEffects.filter((effect) => effect.effect === 'require_project_fact_gate')
    const conditionFields = projectFactEffects.flatMap((effect) => effect.when.map((condition) => condition.field))
    const l5Audit = (
      report.dependencySystemCloseout.trustHardening as typeof report.dependencySystemCloseout.trustHardening & {
        l5ScenarioConstraintAudit?: {
          dependencyGeneratorRuleCount: number
          durationOwningRuleCount: number
          nonBuildingInfrastructureRuleCount: number
          familyCoverage: Array<{
            family: string
            ruleCount: number
            matchedRuleCount: number
            dependencyGeneratorRuleCount: number
            durationOwningRuleCount: number
            ruleCodes: string[]
          }>
        }
      }
    ).l5ScenarioConstraintAudit
    const mepFamily = l5Audit?.familyCoverage.find((item) => item.family === 'mep_testing_commissioning')
    const matchedCrossScopePairs = report.processConstraintCoverage.matchedPairsByRuleCode[rule.stableCode] ?? []
    const sampledFinishClosureStableEdges = [
      '05-01-09->DEC-02-01-02',
      '05-01-09->DEC-02-01-03',
      '05-02-04->DEC-02-01-02',
      '05-02-04->DEC-02-01-03',
    ]
    const matchedExampleStableCodes = new Set(
      matchedCrossScopePairs.flatMap((pair) => pair.exampleStableCodes),
    )
    const stillUnmatchedTargetPairs = processConstraintBackValidation.topUnmatchedExistingRelationEdges.filter((pair) => (
      ['系统调试', '试运行', '试验与调试'].includes(pair.predecessorName)
      && [
        '吊顶',
        '整体面层吊顶',
        '板块面层吊顶',
        '格栅吊顶',
        '吊顶与墙面系统',
        '一般抹灰',
        '墙面涂饰裱糊与软包',
        '木饰面金属饰面安装',
      ].includes(pair.successorName)
    ))

    expect(matchedRuleCodes[rule.stableCode] ?? 0, `${rule.stableCode} must match existing MEP commissioning to finish-closure edges`)
      .toBeGreaterThan(0)
    expect(matchedCrossScopePairs.length, `${rule.stableCode} must enhance cross-scope edges rather than same-parent activity steps`)
      .toBeGreaterThan(0)
    expect(rule.standardCatalogCodePrefixes).toEqual(expect.arrayContaining([
      '06-01-07',
      '08-01-04',
      'DEC-02-01-02',
      'DEC-02-01-03',
    ]))
    for (const expectedStableEdge of sampledFinishClosureStableEdges) {
      expect(matchedExampleStableCodes.has(expectedStableEdge), `${rule.stableCode} must cover ${expectedStableEdge} via structured code matching`)
        .toBe(true)
    }
    expect(matchedCrossScopePairs.every((pair) => (pair.matchQualities.structured_code ?? 0) === pair.count))
      .toBe(true)
    expect(stillUnmatchedTargetPairs, 'high-frequency MEP commissioning to finish closure edges should leave the unmatched backlog')
      .toHaveLength(0)
    expect(rule.applicationMode).toBe('gate_wait')
    expect(rule.constraintType).toBe('commissioning_wait')
    expect(rule.relationshipScope).toBe('cross_scope_edge')
    expect(rule.supportedRelationKinds).toEqual(['explicit_task_dependency'])
    expect(rule.impactMode).toBe('confidence_only')
    expect(rule.runtimeActionPolicy).toBe('confidence_only')
    expect(rule.timeSourcePolicy).toBe('project_fact_then_standard_work_duration')
    expect(rule.durationAuthorityPolicy).toBe('no_duration_values_in_process_constraint')
    expect(rule.dependencyCreationPolicy).toBe('never_create_dependency')
    expect(rule.relationInputPolicy).toBe('requires_existing_relation')
    expect(rule.durationDoubleCountPolicy).toBe('standard_work_duration_owns_all_day_values_process_constraint_owns_edge_routing')
    expect(rule.boundaryPolicyNotes).toEqual(expect.arrayContaining([
      'standard_internal_flow, cross_item_workflow, and dependency_intent_templates own relationship creation; this rule never creates dependencies on its own.',
      'process_constraint never stores commissioning, testing, finish-closure, ceiling, plaster, wall-finish, veneer-finish, report, retest, waiting, lag, or day values.',
    ]))
    expect(projectFactEffects.length).toBeGreaterThan(0)
    expect(conditionFields).toEqual(expect.arrayContaining(['project_type_code', 'method_variant_code']))
    expect(projectFactEffects.every((effect) => (effect.evidenceSourceKeys?.length ?? 0) > 0)).toBe(true)
    expect(projectFactEffects.every((effect) => effect.quantityEvidenceRequirement === 'not_applicable')).toBe(true)
    expect(mepFamily, 'MEP finish-closure release rule must stay in the MEP testing family')
      .toBeTruthy()
    expect(mepFamily!.dependencyGeneratorRuleCount).toBe(0)
    expect(mepFamily!.durationOwningRuleCount).toBe(0)
    expect(l5Audit).toEqual(expect.objectContaining({
      dependencyGeneratorRuleCount: 0,
      durationOwningRuleCount: 0,
      nonBuildingInfrastructureRuleCount: 0,
    }))
    expect(processConstraintCoverage.keywordFallbackMatchedEdgeCount).toBe(0)
  })

