      expect(rule.constraintType).toBe(scenario.expectedConstraintType)
      expect(rule.relationshipScope).toBe('cross_scope_edge')
      expect(rule.supportedRelationKinds).toEqual(['explicit_task_dependency'])
      expect(rule.impactMode).toBe('confidence_only')
      expect(rule.runtimeActionPolicy).toBe('confidence_only')
      expect(rule.timeSourcePolicy).toBe('project_fact_then_standard_work_duration')
      expect(rule.durationAuthorityPolicy).toBe('no_duration_values_in_process_constraint')
      expect(rule.dependencyCreationPolicy).toBe('never_create_dependency')
      expect(rule.relationInputPolicy).toBe('requires_existing_relation')
      expect(rule.durationDoubleCountPolicy).toBe('standard_work_duration_owns_all_day_values_process_constraint_owns_edge_routing')
      expect(rule.standardCatalogCodePrefixes).toEqual([...scenario.expectedPrefixes])
