      expect(projectFactEffects.every((effect) => (effect.evidenceSourceKeys?.length ?? 0) > 0)).toBe(true)
      expect(projectFactEffects.every((effect) => effect.quantityEvidenceRequirement === 'not_applicable')).toBe(true)
