    const matchedRoomPairs = report.processConstraintCoverage.topCrossScopeMatchedPairs.filter((pair) => (
      pair.matchedRuleCodes.includes(roomRule.stableCode)
    ))
    const matchedDecStableEdges = new Set(matchedDecPairs.flatMap((pair) => pair.exampleStableCodes))
    const matchedRoomStableEdges = new Set(matchedRoomPairs.flatMap((pair) => pair.exampleStableCodes))
    const stillUnmatchedTargetPairs = processConstraintBackValidation.topUnmatchedExistingRelationEdges
      .flatMap((pair) => pair.exampleStableCodes)
