  it('splits HVA duct fabrication-installation handoffs into ceiling and wall L5 facts while excluding public-room false carriers', () => {
    const report = collectConstructionDependencyRuleSystemReport(20000)
    const ceilingRule = constraintRule('hvac_duct_installation_to_ceiling_closure_release_gate')
    const wallRule = constraintRule('hvac_duct_installation_to_wall_veneer_finish_release_gate')
    const publicRoomRule = constraintRule('hvac_duct_installation_to_public_room_finish_release_gate')
    const publicRoomL3Rule = crossRule('mep_rough_in_to_public_room_finish_close') as ReturnType<typeof crossRule> & { excludedPredecessorCodePrefixes?: string[] }
    const concealedL3Rule = crossRule('concealed_mep_acceptance_to_ceiling_wall_closure') as ReturnType<typeof crossRule> & { excludedPredecessorCodePrefixes?: string[] }
    const ceilingSuccessors = ['03-05', '03-05-01', '03-05-02', '03-05-03', 'DEC-02-01', 'DEC-02-01-01']
    const wallSuccessors = ['DEC-02-01-02', 'DEC-02-01-03']
    const publicRoomSuccessors = ['DEC-05-01', 'DEC-05-01-01', 'DEC-05-01-02']
    const expectedCeilingEdges = ceilingSuccessors.map((successorCode) => `HVA-01-01-01->${successorCode}`)
    const expectedWallEdges = wallSuccessors.map((successorCode) => `HVA-01-01-01->${successorCode}`)
    const falsePublicRoomEdges = publicRoomSuccessors.map((successorCode) => `HVA-01-01-01->${successorCode}`)
    const l5UnmatchedStableEdges = report.processConstraintBackValidation.topUnmatchedExistingRelationEdges
      .flatMap((pair) => pair.exampleStableCodes)
    const ceilingMatchedEdges = new Set(
      (report.processConstraintCoverage.matchedPairsByRuleCode[ceilingRule.stableCode] ?? [])
        .flatMap((pair) => pair.exampleStableCodes),
    )
    const wallMatchedEdges = new Set(
      (report.processConstraintCoverage.matchedPairsByRuleCode[wallRule.stableCode] ?? [])
        .flatMap((pair) => pair.exampleStableCodes),
    )
    const publicRoomMatchedEdges = new Set(
      (report.processConstraintCoverage.matchedPairsByRuleCode[publicRoomRule.stableCode] ?? [])
        .flatMap((pair) => pair.exampleStableCodes),
    )

    for (const expectedEdge of expectedCeilingEdges) {
      expect(ceilingMatchedEdges.has(expectedEdge), `${ceilingRule.stableCode} must cover ${expectedEdge} via structured code matching`)
        .toBe(true)
    }
    for (const expectedEdge of expectedWallEdges) {
      expect(wallMatchedEdges.has(expectedEdge), `${wallRule.stableCode} must cover ${expectedEdge} via structured code matching`)
        .toBe(true)
    }
    expect(l5UnmatchedStableEdges.filter((stableEdge) => (
      expectedCeilingEdges.includes(stableEdge)
      || expectedWallEdges.includes(stableEdge)
      || falsePublicRoomEdges.includes(stableEdge)
    )), 'HVA-01-01-01 ceiling/wall facts should leave L5 unmatched and public-room false carriers should be removed at L3')
      .toHaveLength(0)
    expect(ceilingRule.standardCatalogCodePrefixes).toEqual(expect.arrayContaining(['HVA-01-01-01']))
    expect(wallRule.standardCatalogCodePrefixes).toEqual(expect.arrayContaining(['HVA-01-01-01']))
    expect(publicRoomRule.standardCatalogCodePrefixes).not.toEqual(expect.arrayContaining(['HVA-01-01-01']))
    expect(publicRoomL3Rule.excludedPredecessorCodePrefixes).toEqual(expect.arrayContaining(['HVA-01-01-01']))
    expect(concealedL3Rule.excludedPredecessorCodePrefixes).toEqual(expect.arrayContaining(['HVA-01-01-01']))
    expect(Array.from(publicRoomMatchedEdges).filter((stableEdge) => falsePublicRoomEdges.includes(stableEdge)))
      .toHaveLength(0)
    expect(report.runtimeMetrics.cross_item_workflow.zeroMatchRuleCount).toBe(0)
    expect(report.runtimeMetrics.process_constraint.keywordFallbackMatchedEdgeCount).toBe(0)
  })

