    expect(forbiddenMatchedEdges, `${rule.stableCode} must not cover specialty HVAC insulation, DEC ceiling-base, 03-05, plaster, floor, or public-room finish edges`)
      .toHaveLength(0)
    expect(stillUnmatchedTargetPairs, `${rule.stableCode} target edges should leave the unmatched backlog`)
