    const matchedRuntimeStableEdges = Array.from(new Set(
      matchedRuntimeRows.flatMap((pair) => pair.exampleStableCodes),
    )).sort()
    const matchedRuntimeEdgeCount = matchedRuntimeRows.reduce((sum, pair) => sum + pair.count, 0)
    const stillUnmatchedTargetPairs = processConstraintBackValidation.topUnmatchedExistingRelationEdges
      .flatMap((pair) => pair.exampleStableCodes)
