  it('keeps L2-owned steel welding appearance inspection manual anchors out of the L5 unmatched back-validation queue', () => {
    const report = collectConstructionDependencyRuleSystemReport(20000)
    const l2OwnedWeldingAppearanceEdges = [
      '02-04-03-P04->02-04-03-P05',
      '02-05-01-P04->02-05-01-P05',
    ]
    const l5UnmatchedStableEdges = report.processConstraintBackValidation.topUnmatchedExistingRelationEdges
      .flatMap((pair) => pair.exampleStableCodes)

    for (const stableEdge of l2OwnedWeldingAppearanceEdges) {
      const [predecessorStableCode, successorStableCode] = stableEdge.split('->')
      const rule = resolveStandardInternalFlowRule({
        predecessorStableCode,
        predecessorName: chinaCatalogNodeNameByStableCode(predecessorStableCode, 'process'),
        successorStableCode,
        successorName: chinaCatalogNodeNameByStableCode(successorStableCode, 'process'),
        successorCategoryType: 'process',
        catalogSource: 'china_gb50300_template_catalog',
      })

      expect(rule.seedRuleId, `${stableEdge} should be owned by the L2 manual welding appearance rule`)
        .toContain('welding-formal-to-weld-appearance-check')
      expect(rule.scope).toBe('same_parent')
      expect(rule.curationStatus).toBe('curated')
      expect(rule.curationMethod).toBe('manual_registry')
      expect(rule.governancePriority).toBe('P2')
      expect(rule.reviewNeeded).toBe(false)
      expect(rule.relationKind).toBe('acceptance_gate')
      expect(rule.relationRole).toBe('inspection')
      expect(rule.createsDependency).toBe(true)
      expect(rule.dependencyType).toBe('FS')
      expect(rule.lagDays).toBe(0)
      expect(rule.evidenceCodes).toEqual(expect.arrayContaining(['GB50205', 'GB50300']))
      expect(l5UnmatchedStableEdges, `${stableEdge} is a same-parent L2 welding appearance inspection anchor and must not remain in the L5 unmatched queue`)
        .not.toContain(stableEdge)
    }
    expect(report.runtimeMetrics.process_constraint.keywordFallbackMatchedEdgeCount).toBe(0)
  })

