  it('keeps current hotel room internal orders and transformer energy parent carriers out of L5 back-validation', () => {
    const report = collectConstructionDependencyRuleSystemReport(80)
    const topUnmatchedStableEdges = report.processConstraintBackValidation.topUnmatchedExistingRelationEdges
      .flatMap((pair) => pair.exampleStableCodes)
    const hotelInternalEdges = [
      ['HTL-01-01-02-P01', 'HTL-01-01-02-P02', 'hard_sequence'],
      ['HTL-01-01-02-P04', 'HTL-01-01-02-P05', 'acceptance_gate'],
    ] as const
    const broadEnergyParentEdges = [
      '07-01-01->09-03',
      '07-01-01->09-03-01',
      '07-01-01->09-03-02',
    ]

    for (const [predecessorStableCode, successorStableCode, relationKind] of hotelInternalEdges) {
      const stableEdge = `${predecessorStableCode}->${successorStableCode}`
      const rule = resolveStandardInternalFlowRule({
        predecessorStableCode,
        predecessorName: domainWbsNodeNameByStableCode('china-hotel-specialty', predecessorStableCode, 'process'),
        successorStableCode,
        successorName: domainWbsNodeNameByStableCode('china-hotel-specialty', successorStableCode, 'process'),
        successorCategoryType: 'process',
        catalogSource: 'domain_wbs_template_catalog',
      })

      expect(rule.curationStatus, `${stableEdge} must stay curated L2`).toBe('curated')
      expect(rule.curationMethod, `${stableEdge} must stay stable-code L2 backfill`).toBe('stable_code_backfill')
      expect(rule.scope, `${stableEdge} must stay same-parent L2`).toBe('same_parent')
      expect(rule.relationKind, `${stableEdge} relation kind`).toBe(relationKind)
      expect(rule.createsDependency, `${stableEdge} must be created by L2, not L5`).toBe(true)
      expect(rule.reviewNeeded).toBe(false)
      expect(topUnmatchedStableEdges, `${stableEdge} must not remain in the L5 unmatched back-validation queue`)
        .not.toContain(stableEdge)
    }

    expect(topUnmatchedStableEdges.filter((stableEdge) => broadEnergyParentEdges.includes(stableEdge)), 'Transformer parent to energy-efficiency parent carriers are broad false carriers, not confirmed L3 or L5 fact gates')
      .toHaveLength(0)
    expect(report.runtimeMetrics.process_constraint.keywordFallbackMatchedEdgeCount).toBe(0)
    expect(report.runtimeMetrics.cross_item_workflow.zeroMatchRuleCount).toBe(0)
  })

