  it('keeps data-center perimeter trial-run closeout as an L2 final-acceptance gate instead of a supplemental-work predecessor', () => {
    const supplementalNames = new Set([
      '周界摄像机探测器安装作业',
      '电子巡更点位安装作业',
      '夜间补光联动测试作业',
    ])
    const rules = STANDARD_INTERNAL_FLOW_RULE_SEED.filter((rule) => (
      rule.matchMode === 'stable_code'
      && (
        rule.predecessorStableCode?.startsWith('DTC-04-01-21-')
        || rule.successorStableCode?.startsWith('DTC-04-01-21-')
      )
    ))
    const trialRunBeforeSupplementalWork = rules
      .filter((rule) => rule.predecessorName === '安保试运行巡检' && supplementalNames.has(rule.successorName))
      .map((rule) => `${rule.predecessorStableCode}->${rule.successorStableCode}:${rule.predecessorName}->${rule.successorName}`)

    expect(
      trialRunBeforeSupplementalWork,
      'security trial-run closeout must not release later supplemental field installation or linkage work',
    ).toEqual([])

    const finalAcceptanceRule = rules.find((rule) => (
      rule.predecessorStableCode === 'DTC-04-01-21-P08'
      && rule.successorStableCode === 'DTC-04-01-21-P09'
    ))
    expect(finalAcceptanceRule, 'security trial-run closeout should release perimeter security acceptance').toBeTruthy()
    expect(finalAcceptanceRule!.relationKind).toBe('acceptance_gate')
    expect(finalAcceptanceRule!.dependencyType).toBe('FS')
    expect(finalAcceptanceRule!.conditionalEffects).toEqual(expect.arrayContaining([
      expect.objectContaining({
        id: 'tiered-data-center-security-acceptance-after-trial-run-closeout',
        dependencyType: 'FS',
        scheduleMode: 'sequential',
        reasonCode: 'TIERED_DATA_CENTER_SECURITY_ACCEPTANCE_AFTER_TRIAL_RUN_CLOSEOUT',
      }),
    ]))

    const effect = finalAcceptanceRule!.conditionalEffects.find((candidate) => (
      candidate.id === 'tiered-data-center-security-acceptance-after-trial-run-closeout'
    ))
    expect(effect?.evidenceRefs?.length).toBeGreaterThan(0)
  })

