  it('keeps heritage formal restoration internal flow rules tied to real WBS process names rather than placeholder depth labels', () => {
    const auditedItemCodes = [
      'HRT-04-01-01',
      'HRT-04-01-02',
      'HRT-04-01-03',
      'HRT-04-01-04',
      'HRT-04-01-05',
      'HRT-04-01-06',
      'HRT-04-01-07',
      'HRT-04-01-08',
      'HRT-04-01-09',
      'HRT-04-01-10',
      'HRT-04-01-11',
      'HRT-04-01-12',
      'HRT-04-01-13',
      'HRT-04-01-14',
      'HRT-04-01-15',
    ]
    const placeholderNamePattern = /\bheritage .* (checkpoint|work|closeout|retest|handover)\b/i
    const hrtStableCodeRules = STANDARD_INTERNAL_FLOW_RULE_SEED.filter((rule) => (
      rule.matchMode === 'stable_code'
      && (
        rule.predecessorStableCode?.startsWith('HRT-04-')
        || rule.successorStableCode?.startsWith('HRT-04-')
      )
    ))

    expect(hrtStableCodeRules.length, 'HRT-04 should have curated internal flow rules').toBeGreaterThan(0)
    const duplicateStableCodePairs = hrtStableCodeRules
      .map((rule) => `${rule.predecessorStableCode}->${rule.successorStableCode}`)
      .filter((pair, index, pairs) => pairs.indexOf(pair) !== index)
    expect(duplicateStableCodePairs, 'HRT-04 stable-code rules must not duplicate the same edge').toEqual([])
    for (const rule of hrtStableCodeRules) {
      expect(rule.predecessorName, `${rule.predecessorStableCode} placeholder name`).not.toMatch(placeholderNamePattern)
      expect(rule.successorName, `${rule.successorStableCode} placeholder name`).not.toMatch(placeholderNamePattern)
      expect(rule.predecessorName, `${rule.predecessorStableCode} must use the WBS process name`)
        .toBe(domainWbsProcessNameByStableCode(
          'china-heritage-preservation-specialty',
          rule.predecessorStableCode!,
        ))
      expect(rule.successorName, `${rule.successorStableCode} must use the WBS process name`)
        .toBe(domainWbsProcessNameByStableCode(
          'china-heritage-preservation-specialty',
          rule.successorStableCode!,
        ))
    }

    for (const itemCode of auditedItemCodes) {
      const targetPairs = itemCode === 'HRT-04-01-15'
        ? [
          [`${itemCode}-P05`, `${itemCode}-P08`],
          [`${itemCode}-P09`, `${itemCode}-P10`],
        ] as const
        : [
          [`${itemCode}-P05`, `${itemCode}-P07`],
          [`${itemCode}-P08`, `${itemCode}-P09`],
        ] as const

      for (const [predecessorStableCode, successorStableCode] of targetPairs) {
        const expectedPredecessorName = domainWbsProcessNameByStableCode(
          'china-heritage-preservation-specialty',
          predecessorStableCode,
        )
        const expectedSuccessorName = domainWbsProcessNameByStableCode(
          'china-heritage-preservation-specialty',
          successorStableCode,
        )
        const rule = STANDARD_INTERNAL_FLOW_RULE_SEED.find((candidate) => (
          candidate.matchMode === 'stable_code'
          && candidate.predecessorStableCode === predecessorStableCode
          && candidate.successorStableCode === successorStableCode
        ))

        expect(rule, `${predecessorStableCode}->${successorStableCode} stable-code rule`).toBeTruthy()

        const resolved = resolveStandardInternalFlowRule({
          predecessorStableCode,
          predecessorName: expectedPredecessorName,
          successorStableCode,
          successorName: expectedSuccessorName,
          successorCategoryType: 'process',
          catalogSource: 'domain_wbs_template_catalog',
        })

        expect(resolved.curationStatus, `${predecessorStableCode}->${successorStableCode}`).toBe('curated')
        expect(resolved.curationMethod, `${predecessorStableCode}->${successorStableCode}`).toBe('stable_code_backfill')
        expect(resolved.reviewNeeded, `${predecessorStableCode}->${successorStableCode}`).toBe(false)
        expect(resolved.relationKind, `${predecessorStableCode}->${successorStableCode}`).toBe('acceptance_gate')
        expect(resolved.createsDependency, `${predecessorStableCode}->${successorStableCode}`).toBe(true)
        expect(resolved.dependencyType, `${predecessorStableCode}->${successorStableCode}`).toBe('FS')
        expect(resolved.evidenceCodes, `${predecessorStableCode}->${successorStableCode}`)
          .toEqual(expect.arrayContaining(['GB50300']))
      }
    }
  })

