  it('keeps every hospital cleanroom stable-code internal flow rule aligned to current WBS nodes', () => {
    const clnStableCodeRules = STANDARD_INTERNAL_FLOW_RULE_SEED.filter((rule) => (
      rule.matchMode === 'stable_code'
      && (
        rule.predecessorStableCode?.startsWith('CLN-')
        || rule.successorStableCode?.startsWith('CLN-')
      )
    ))
    const stableCodePairs = clnStableCodeRules
      .map((rule) => `${rule.predecessorStableCode}->${rule.successorStableCode}`)
    const duplicateStableCodePairs = stableCodePairs
      .filter((pair, index, pairs) => pairs.indexOf(pair) !== index)
    const nameDrift = clnStableCodeRules.flatMap((rule) => {
      const expectedPredecessorName = domainWbsNodeNameByStableCode(
        'china-cleanroom-medical-specialty',
        rule.predecessorStableCode!,
      )
      const expectedSuccessorName = domainWbsNodeNameByStableCode(
        'china-cleanroom-medical-specialty',
        rule.successorStableCode!,
      )
      const drift: string[] = []
      if (rule.predecessorName !== expectedPredecessorName) {
        drift.push(`${rule.predecessorStableCode} predecessor "${rule.predecessorName}" != "${expectedPredecessorName}"`)
      }
      if (rule.successorName !== expectedSuccessorName) {
        drift.push(`${rule.successorStableCode} successor "${rule.successorName}" != "${expectedSuccessorName}"`)
      }
      return drift
    })

    expect(clnStableCodeRules.length, 'CLN should have a meaningful curated stable-code internal-flow surface')
      .toBeGreaterThan(100)
    expect(duplicateStableCodePairs, 'CLN stable-code rules must not duplicate the same edge').toEqual([])
    expect(nameDrift, 'CLN stable-code rules must use current WBS process names').toEqual([])
  })

