  it('promotes insulation seam sealing to cold-bridge review edges as L2 same-parent internal acceptance gates', () => {
    const cases = [
      {
        predecessorStableCode: '06-13-06-P07',
        successorStableCode: '06-13-06-P08',
        expectedSuccessorName: /冷桥|结露/,
      },
      {
        predecessorStableCode: '06-16-05-P07',
        successorStableCode: '06-16-05-P08',
        expectedSuccessorName: /冷桥|结露/,
      },
      {
        predecessorStableCode: '06-10-08-P07',
        successorStableCode: '06-10-08-P08',
        expectedSuccessorName: /防结露|滴水/,
      },
      {
        predecessorStableCode: '06-11-07-P07',
        successorStableCode: '06-11-07-P08',
        expectedSuccessorName: /冷桥|结露/,
      },
      {
        predecessorStableCode: '06-12-06-P07',
        successorStableCode: '06-12-06-P08',
        expectedSuccessorName: /冷桥|结露|室外防护/,
      },
      {
        predecessorStableCode: '06-14-07-P07',
        successorStableCode: '06-14-07-P08',
        expectedSuccessorName: /冷桥|结露|防冻/,
      },
    ] as const
    const report = collectConstructionDependencyRuleSystemReport(20000)
    const topL5UnmatchedStableEdges = report.processConstraintBackValidation.topUnmatchedExistingRelationEdges
      .flatMap((pair) => pair.exampleStableCodes)

    for (const currentCase of cases) {
      const predecessorName = chinaCatalogNodeNameByStableCode(currentCase.predecessorStableCode, 'process')
      const successorName = chinaCatalogNodeNameByStableCode(currentCase.successorStableCode, 'process')
      const rule = resolveStandardInternalFlowRule({
        predecessorStableCode: currentCase.predecessorStableCode,
        predecessorName,
        successorStableCode: currentCase.successorStableCode,
        successorName,
        successorCategoryType: 'process',
        catalogSource: 'china_gb50300_template_catalog',
      })
      const sourceRule = STANDARD_INTERNAL_FLOW_RULE_SEED.find((seed) => (
        seed.id === `stable-code-${currentCase.predecessorStableCode}-to-${currentCase.successorStableCode}`
      ))
      const stableEdge = `${currentCase.predecessorStableCode}->${currentCase.successorStableCode}`

      expect(predecessorName).toMatch(/接缝密封|破损修补/)
      expect(successorName).toMatch(currentCase.expectedSuccessorName)
      expect(rule.seedRuleId).toContain(`stable-code-${currentCase.predecessorStableCode}-to-${currentCase.successorStableCode}`)
      expect(rule.curationStatus).toBe('curated')
      expect(rule.curationMethod).toBe('stable_code_backfill')
      expect(rule.reviewNeeded).toBe(false)
      expect(rule.relationKind).toBe('acceptance_gate')
      expect(rule.createsDependency).toBe(true)
      expect(rule.dependencyType).toBe('FS')
      expect(rule.lagDays).toBe(0)
      expect(rule.evidenceCodes).toEqual(expect.arrayContaining(['GB50243', 'GB50300']))
      expect(rule.evidenceRefs.map((ref) => ref.code)).toEqual(expect.arrayContaining(['GB50243', 'GB50300']))
      expect(rule.evidenceRefs.map((ref) => ref.rationale ?? '').join(' '))
        .toMatch(/same-parent|same itemPack|L2|internal|cold-bridge|condensation|review/i)
      expect(rule.curationBasis).toMatch(/same-parent|same itemPack|L2|internal|acceptance|cold-bridge|condensation|review/i)
      expect(sourceRule?.applicableCategoryTypes).toEqual(['process'])
      expect(sourceRule?.createsDependency).toBe(true)
      expect(sourceRule?.relationKind).toBe('acceptance_gate')
      expect(topL5UnmatchedStableEdges, `${stableEdge} is L2-owned and must not remain in the L5 unmatched back-validation queue`)
        .not.toContain(stableEdge)
    }
  })

