  it('classifies weak L2 runtime anchors before any further schedule-trust promotion', () => {
    const standardReport = collectCachedStandardInternalFlowGovernanceReport(160)
    const audit = standardReport.evidenceStrengthAudit as typeof standardReport.evidenceStrengthAudit & {
      weakRuntimeAnchorClassificationPolicy: string
      l2PhysicalUpgradeCandidateCount: number
      weakRuntimeAnchorClassificationCounts: Record<string, number>
      weakRuntimeAnchorClassificationSamples: Record<string, Array<{
        predecessorStableCode: string
        successorStableCode: string
        predecessorName: string
        successorName: string
        relationKind: string
        runtimeTreatment: string
        weakRuntimeAnchorCategory?: string
        weakRuntimeAnchorCategoryReason?: string
        suspectedDependencyLayer?: string
        exactL5ProcessConstraintCovered?: boolean
        exactL5ProcessConstraintRuleCode?: string | null
      }>>
    }
    const counts = audit.weakRuntimeAnchorClassificationCounts

    expect(audit.weakRuntimeAnchorClassificationPolicy)
      .toMatch(/classification|L2|L4|L5|promotion/i)
    expect(Object.values(counts).reduce((total, count) => total + count, 0))
      .toBe(audit.weakRuntimeAnchorUpgradeQueueCount)
    expect(audit.l2PhysicalUpgradeCandidateCount)
      .toBe(counts.l2_physical_sequence_candidate)
    expect(counts.l2_physical_sequence_candidate).toBeGreaterThan(0)
    expect(counts.l5_process_constraint_candidate).toBeGreaterThan(0)
    expect(counts.l4_business_gate_candidate).toBeGreaterThan(0)
    expect(counts.acceptance_inspection_test_candidate).toBeGreaterThan(0)
    expect(counts.document_report_handover_candidate).toBeGreaterThan(0)
    expect(counts.review_required_or_non_l2_candidate).toBeGreaterThan(0)

    const nonL2CandidateTotal = (
      counts.l5_process_constraint_candidate
      + counts.l4_business_gate_candidate
      + counts.acceptance_inspection_test_candidate
      + counts.document_report_handover_candidate
      + counts.review_required_or_non_l2_candidate
    )
    expect(nonL2CandidateTotal).toBeGreaterThan(0)

    const forbiddenL2Semantics = /检测|检验|试验|测试|复测|复核|复查|复验|核验|验收|检查|抽查|抽测|巡查|评定|探伤|校验|确认|观察|移交|交接|联调|调试|试运行|报告|资料|记录|归档|审批|放行|签认|备案|养护|龄期|强度|保压|试压|冲洗|消毒|监测|观测|handover|acceptance|test|report|archive|commission|confirm|verify/i
    for (const sample of audit.weakRuntimeAnchorClassificationSamples.l2_physical_sequence_candidate ?? []) {
      const text = `${sample.predecessorName} ${sample.successorName} ${sample.relationKind} ${sample.runtimeTreatment}`
      expect(text, `${sample.predecessorName}->${sample.successorName} must not be a hidden L4/L5/test/report tail`)
        .not.toMatch(forbiddenL2Semantics)
      expect(sample.relationKind).toBe('hard_sequence')
    }

    const closeoutReport = collectConstructionDependencyRuleSystemReport(160)
    const closeoutAudit = closeoutReport.dependencySystemCloseout.trustHardening.l2ReverseCoverage.evidenceStrengthAudit as typeof audit
    expect(closeoutAudit.weakRuntimeAnchorUpgradeQueueCount)
      .toBe(audit.weakRuntimeAnchorUpgradeQueueCount)
    expect(closeoutAudit.weakRuntimeAnchorClassificationCounts)
      .toEqual(audit.weakRuntimeAnchorClassificationCounts)
    expect(closeoutAudit.weakRuntimeAnchorClassificationSamples.l5_process_constraint_candidate.length)
      .toBeGreaterThan(0)

    const exactL5CoveredStableEdge = '01-02-09-P08->01-02-09-P09'
    const exactL5CoveredSample = (audit.weakRuntimeAnchorClassificationSamples.l5_process_constraint_candidate ?? [])
      .find((sample) => `${sample.predecessorStableCode}->${sample.successorStableCode}` === exactL5CoveredStableEdge)
    const exactL5CoveredRule = constraintRule('pile_top_protection_to_integrity_detection_release_gate')
    const exactL5CoveredRows = closeoutReport.processConstraintCoverage.matchedPairsByRuleCode[exactL5CoveredRule.stableCode] ?? []

    expect(exactL5CoveredSample, `${exactL5CoveredStableEdge} should stay visible as a weak L2 anchor that is already covered by an exact L5 fact gate`).toBeTruthy()
    expect(exactL5CoveredSample?.weakRuntimeAnchorCategory).toBe('l5_process_constraint_candidate')
    expect(exactL5CoveredSample?.suspectedDependencyLayer).toBe('L5')
    expect(exactL5CoveredSample?.weakRuntimeAnchorCategoryReason)
      .toMatch(/process_constraint|wait|commissioning|environment/i)
    expect(exactL5CoveredSample?.exactL5ProcessConstraintCovered).toBe(true)
    expect(exactL5CoveredSample?.exactL5ProcessConstraintRuleCode).toBe(exactL5CoveredRule.stableCode)
    expect(exactL5CoveredRows.flatMap((pair) => pair.exampleStableCodes)).toContain(exactL5CoveredStableEdge)
  })

  it('keeps operation and system-configuration tails out of the L2 physical promotion queue', () => {
    const standardReport = collectCachedStandardInternalFlowGovernanceReport(10000)
    const weakQueue = standardReport.evidenceStrengthAudit.weakRuntimeAnchorUpgradeQueue as Array<{
      predecessorStableCode: string
      successorStableCode: string
      predecessorName: string
      successorName: string
      weakRuntimeAnchorCategory?: string
      weakRuntimeAnchorCategoryReason?: string
      suspectedDependencyLayer?: string
    }>
    const sampleByEdge = new Map(
      weakQueue.map((sample) => [`${sample.predecessorStableCode}->${sample.successorStableCode}`, sample]),
    )
    const operationalOrConfigurationEdges = [
      'CMP-04-01-01-P02->CMP-04-01-01-P03',
      'CMP-05-01-30-P02->CMP-05-01-30-P03',
      'CMP-05-01-30-P04->CMP-05-01-30-P05',
      'HTL-05-01-01-P01->HTL-05-01-01-P02',
      'DTC-04-01-05-P05->DTC-04-01-05-P06',
      'ICR-05-01-25-P03->ICR-05-01-25-P04',
      'HTL-06-01-22-P04->HTL-06-01-22-P05',
    ]

    for (const edge of operationalOrConfigurationEdges) {
      const sample = sampleByEdge.get(edge)
      expect(sample, `${edge} should remain visible in the weak-anchor governance queue before manual routing`).toBeTruthy()
      expect(
        sample?.weakRuntimeAnchorCategory,
        `${edge} (${sample?.predecessorName}->${sample?.successorName}) is operational/configuration work and must not be promoted as clean L2 physical order`,
      ).not.toBe('l2_physical_sequence_candidate')
      expect(sample?.suspectedDependencyLayer).toMatch(/review|L4|L5/)
      expect(sample?.weakRuntimeAnchorCategoryReason).toMatch(/configuration|operation|training|handover|review|business|system/i)
    }
  })

